type item struct {
    id   uint64
    name [16]byte      // payload inline in the struct: no allocation per instance
    n    uint8
}
func (it *item) setName(s string) bool {   // small values are stored by value, not boxed
    if len(s) > len(it.name) {
        return false                       // spill case: caller keeps a growable buffer
    }
    it.n = uint8(copy(it.name[:], s))
    return true
}
